    occlusionPass: RenderPassLensFlareOcclusion;
    /** @type {RenderPassLensFlareSprites} */
    spritePass: RenderPassLensFlareSprites;
    /** @type {Texture[]} */
    visibilityTextures: Texture[];
    /** @type {RenderTarget[]} */
    visibilityTargets: RenderTarget[];
    /** @private */
    private _visibilityIndex;
    /** @private */
    private _flareTarget;
    /**
     * Sets the per-flare arrays the passes read every frame.
     *
     * @param {Float32Array} flareData - The flare data.
     * @param {Float32Array} occlusionData - The occlusion data.
     */
    setFlareData(flareData: Float32Array, occlusionData: Float32Array): void;
